"use strict";

require("approot/global/controllers/registryCtrl.js");

angular
	.module("irtech.netcity.admin.stats")
	.controller("UserStatCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts) => {

		$scope.$parent.page = {
			title: language.Generic.ServAdmin.kTitleUserStat,
			parent: {
				title: language.Generic.MenuFolders.kFSAStatistics,
				href: `/usermon/`
			}
		};

		$scope.registry = {
			url:  "/webapi/admin/userstat/registry",
			filtersUrl: "/webapi/admin/userstat/registry/filter",
			fieldDecorators: {
				"emNames": { type: "preserveWhiteSpace" },
				"roleNames": { type: "text-center" }
			}
		};

		$controller("RegistryCommonCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts });

	});


