"use strict";

import { BaseRepository } from "approot/global/repository.js";

class StatsRepository extends BaseRepository {
	getActiveSessions() {
		return this.$http.get("/webapi/context/activeSessions")
			.catch(this.handleError)
			.then((response) => {
				const sessions = response.data;
				return sessions || [];
			});
	}

	killSessions(ats) {
		return this.$http.delete(`/webapi/context/activeSessions`, {params: {at: ats} })
			.then(() => {
				this.$alerts.success("Сессии успешно удалены");
			})
			.catch(this.handleError);
	}
}

angular
	.module("irtech.netcity.admin.stats")
	.factory("statsRepository", ($http, $dialogs, $alerts) => new StatsRepository($http, $dialogs, $alerts))
;


