//angular = require 'angular'

const module = angular.module("irtech.netcity.admin.stats",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "ngFileUpload", "ui.tree", "irtech.netcity.ui-components",
		"irtech.netcity.directive"
	]);

require("./usermon/usermonCtrl.js");
require("./userEvents/userEventsCtrl.js");
require("./userStat/userStatCtrl.js");
require("./repository.js");

require("approot/global/directives/storageDirective.coffee");

module
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/usermon/", {
				templateUrl: "/static/dist/app/admin/stats/usermon/template.html",
				controller: "UserMonCtrl"
			})
			.when("/userevents/", {
				//templateUrl: "/static/dist/app/admin/stats/userEvents/template.html",
				templateUrl: "/static/dist/app/global/templates/registry.html",
				controller: "UserEventsCtrl"
			})
			.when("/userstat/", {
				//templateUrl: "/static/dist/app/admin/stats/userStat/template.html",
				templateUrl: "/static/dist/app/global/templates/registry.html",
				controller: "UserStatCtrl"
			})
			.otherwise({
				redirectTo: "/usermon/"
			});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



