"use strict";

import MultiSelectable from "approot/global/multiSelectable.js";

angular
	.module("irtech.netcity.admin.stats")
	.controller("UserMonCtrl", ($scope, statsRepository, $appLoader, $location) => {

		$scope.$parent.page = {
			title: language.Generic.MenuFolders.kFSAStatistics + " / " + language.Generic.ServAdmin.kTitleUsermon
		};

		angular.extend($scope,
			{
				language : language,
				data: {
					activeSessions: [],
					selection: new MultiSelectable()
				},
				state: {
					dataReady: false,
					dataEmpty: false
				}
			});

		$scope.loginStats = () => {
			$location.path("/userstat/");
		}

		$scope.errorsStats = () => {
			$location.path("/userevents/");
		}

		$scope.smsStats = () => {
			DoSubmit(document.MenuForm, '/asp/administration/smsstat.asp');
		}

		$scope.delete = (sessions) => {
			let at = _.pluck(sessions, "at");
			statsRepository.killSessions(at).then(() => {
				$scope.load();
			});
		};
		
		$scope.load = () => {

			statsRepository.getActiveSessions().then((activeSessions) => {
				$scope.data.activeSessions = activeSessions;
				$scope.data.selection.dropSelect();

				$scope.state.emptyData = !activeSessions.length;
				$scope.state.dataReady = true;
				$appLoader.hide();
			});
		};

		$scope.load();

	});


