"use strict";

require("approot/global/controllers/registryCtrl.js");

angular
	.module("irtech.netcity.admin.stats")
	.controller("UserEventsCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts) => {

		$scope.$parent.page = {
			title: language.Generic.ServAdmin.kTitleErrorStat,
			parent: {
				title: language.Generic.MenuFolders.kFSAStatistics,
				href: `/usermon/`
			}
		};

		$scope.registry = {
			url:  "/webapi/admin/userevents/registry",
			filtersUrl: "/webapi/admin/userevents/registry/filter"
		};

		$controller("RegistryCommonCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts });

	});


